package com.aistock.market.marketrefs;
import com.aistock.common.*;import com.aistock.common.marketrefs.MarketReferenceRecords.VersionMeta;import java.time.Instant;import java.util.Objects;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.stereotype.Repository;import org.springframework.transaction.TransactionDefinition;import org.springframework.transaction.support.TransactionTemplate;
@Repository public class MarketVersionReferenceRepository {
 private final JdbcTemplate jdbc;private final TransactionTemplate read;
 public MarketVersionReferenceRepository(JdbcTemplate jdbc){this.jdbc=jdbc;read=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);read.setTimeout(5);}
 public VersionMeta meta(String stock,String version,Instant now){try{return read.execute(tx->{var rows=jdbc.query("select v.provider,v.price_basis,v.status,exists(select 1 from instrument_data_head h where h.instrument_id=v.instrument_id and h.version_id=v.version_id and binary h.provider=binary v.provider and binary h.price_basis=binary v.price_basis) current_ref from market_data_version v join instrument i on i.instrument_id=v.instrument_id where v.instrument_id=? and v.version_id=? and i.demo_only=false",(rs,n)->new VersionMeta(stock,version,rs.getString("provider"),rs.getString("price_basis"),rs.getString("status"),rs.getBoolean("current_ref"),now),stock,version);if(rows.size()!=1)throw new BusinessException("MARKET_ADMIN_RESOURCE_NOT_FOUND","未找到所属股票的行情版本",HttpStatus.NOT_FOUND);return rows.get(0);});}catch(org.springframework.dao.DataAccessException|org.springframework.transaction.TransactionException e){throw new BusinessException("MARKET_ADMIN_UNAVAILABLE","行情版本暂无法核对",HttpStatus.SERVICE_UNAVAILABLE);}}
}
